import { bindSetIcon, renderSetIcon } from "../icon-set-core.js";

export const definition = {
  "name": "wallet",
  "category": "Commerce",
  "viewBox": "0 0 24 24",
  "mode": "stroke",
  "strokeWidth": 2,
  "motion": "coin",
  "parts": [
