    {
      "tag": "path",
      "attrs": {
        "d": "M3 5v14a2 2 0 0 0 2 2h15a1 1 0 0 0 1-1v-4"
      }
    }
  ],
  "accents": []
};

export const meta = {
  "slug": "lucide-wallet",
  "family": "lucide",
  "name": "wallet",
  "category": "Commerce",
  "motion": "coin",
  "component": "createLucideWalletIcon"
};

export function createLucideWalletIcon(root, options = {}) {
  let current = { ...options };
  const render = () => {
    root.innerHTML = renderSetIcon(definition, current);
  };
  render();
  const controller = bindSetIcon(root, definition, () => current);
  return {
    play: controller.play,
    reset: controller.reset,
    destroy: controller.destroy,
    update(next = {}) {
      current = { ...current, ...next };
      render();
    },
    get observed() {
      return controller.observed;
    },
  };
}
